def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        self.error('E055a')
        return
    for algorithm in fixity:
        algorithm_map = fixity[algorithm]
        if not isinstance(algorithm_map, dict):
            self.error('E055b', algorithm=algorithm)
            continue
        digest_re = digest_regex(algorithm)
        for digest in algorithm_map:
            m = re.match(digest_re, digest)
            if not m:
                self.error('E057a', digest=digest, algorithm=algorithm)
            elif not isinstance(algorithm_map[digest], list):
                self.error('E057b', digest=digest)
            else:
                for file in algorithm_map[digest]:
                    if manifest_files is None or file not in manifest_files:
                        self.error('E057c', file=file)

