def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    prior_manifest_digests = {}
    prior_fixity_digests = {}
    for version_dir in version_dirs:
        inv_file = version_dir + '/inventory.json'
        if not self.obj_fs.exists(inv_file):
            self.log.warning('W010', where=version_dir)
        else:
            inventory, inv_validator = self.validate_inventory(inv_file, where=version_dir)
            self.validate_inventory_digest(inv_file, inv_validator.digest_algorithm, where=version_dir)
            # Record any digests different from root inventory
            for digest, files in inv_validator.manifest_files.items() if hasattr(inv_validator, 'manifest_files') else []:
                if digest not in self.root_inv_validator.manifest_files:
                    prior_manifest_digests[digest] = files
            for digest, files in inv_validator.fixity_files.items() if hasattr(inv_validator, 'fixity_files') else []:
                prior_fixity_digests[digest] = files
    return prior_manifest_digests, prior_fixity_digests

