    raw = subprocess.run(["git", "-C", ignored, "status", "-s", "--ignored"], capture_output=True, text=True).stdout
    all_entries = raw.strip("\n").splitlines()
    ignored_entries = []
    for entry in all_entries:
        if "!" in entry:
            ignored_entries.append(entry.replace("!", ""))
    return ", ".join(ignored_entries)

